parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "diagnostico_ia": {
      "type": "string",
      "description": "Explicación técnica detallada y concisa de la causa raíz de la falla del ISP."
    },
    "categoria_accion": {
      "type": "string",
      "enum": ["A", "B", "C"],
      "description": "Clasificación del incidente: A para auto-recuperación por SSH, B para escalamiento crítico al NOC, C para atención al cliente/Tier 1."
    },
    "requiere_ssh": {
      "type": "boolean",
      "description": "Verdadero si se necesita ejecutar un comando de diagnóstico o mitigación en el equipo afectado."
    },
    "comando_sugerido": {
      "type": "string",
      "description": "Comando exacto de RouterOS o CLI aplicable si requiere_ssh es true. De lo contrario, dejar como string vacío o null."
    },
    "notificacion_noc": {
      "type": "string",
      "description": "Mensaje formateado en Markdown listo para enviar al canal de alertas de los ingenieros del NOC."
    },
    "ticket_cliente": {
      "type": "string",
      "description": "Mensaje de texto amigable o estructurado para el helpdesk/cliente final si la categoría es C. De lo contrario, dejar vacío."
    }
  },
  "required": [
    "diagnostico_ia",
    "categoria_accion",
    "requiere_ssh",
    "comando_sugerido",
    "notificacion_noc",
    "ticket_cliente"
  ]
}
